<body>
    <div class="container">
        <div class="header">
            <h1>Results</h1>
            <div class="search-box">
                <input 
                    type="text" 
                    id="searchInput" 
                    class="search-input" 
                    placeholder="Filter results..."
                    autocomplete="off"
                >
                <div class="result-count"><span id="rowCount">0</span> of <span id="totalCount">0</span></div>
            </div>
        </div>
        <div class="table-wrapper">
            <table id="dataTable">
                <thead>
                    <tr>
                        <th onclick="sortTable(0)">Name <span class="sort-indicator"></span></th>
                        <th onclick="sortTable(1)">Status <span class="sort-indicator"></span></th>
                        <th onclick="sortTable(2)">Type <span class="sort-indicator"></span></th>
                        <th onclick="sortTable(3)">Created <span class="sort-indicator"></span></th>
                        <th onclick="sortTable(4)">Details <span class="sort-indicator"></span></th>
                    </tr>
                </thead>
                <tbody id="tableBody">
                </tbody>
            </table>
            <div id="emptyState" class="empty-state" style="display: none;">
                <div class="empty-state-icon">🔍</div>
                <div>No results match your filter</div>
            </div>
        </div>
    </div>

    <script>
        const sampleData = [
            { name: 'API Gateway', status: 'active', type: 'service', created: '2026-09-15', details: 'Production endpoint' },
            { name: 'Database Cache', status: 'active', type: 'cache', created: '2026-09-14', details: 'Redis cluster' },
            { name: 'File Storage', status: 'inactive', type: 'storage', created: '2026-09-10', details: 'S3 bucket' },
            { name: 'Message Queue', status: 'active', type: 'queue', created: '2026-09-12', details: 'RabbitMQ instance' },
            { name: 'Auth Service', status: 'active', type: 'service', created: '2026-09-16', details: 'OAuth2 provider' },
            { name: 'Logging System', status: 'active', type: 'monitoring', created: '2026-09-11', details: 'ELK stack' },
            { name: 'Search Index', status: 'maintenance', type: 'database', created: '2026-09-13', details: 'Elasticsearch' },
            { name: 'Backup Storage', status: 'inactive', type: 'storage', created: '2026-09-08', details: 'Archived' },
        ];

        let currentSort = { column: -1, ascending: true };
        let filteredData = [...sampleData];

        function renderTable(data) {
            const tbody = document.getElementById('tableBody');
            const emptyState = document.getElementById('emptyState');

            tbody.innerHTML = '';

            if (data.length === 0) {
                emptyState.style.display = 'block';
                document.getElementById('rowCount').textContent = '0';
                return;
            }

            emptyState.style.display = 'none';
            const searchTerm = document.getElementById('searchInput').value.toLowerCase();

            data.forEach(row => {
                const tr = document.createElement('tr');
                tr.innerHTML = `
                    <td>${highlightMatch(row.name, searchTerm)}</td>
                    <td>${highlightMatch(row.status, searchTerm)}</td>
                    <td>${highlightMatch(row.type, searchTerm)}</td>
                    <td>${highlightMatch(row.created, searchTerm)}</td>
                    <td>${highlightMatch(row.details, searchTerm)}</td>
                `;
                tbody.appendChild(tr);
            });

            document.getElementById('rowCount').textContent = data.length;
        }

        function highlightMatch(text, term) {
            if (!term) return text;
            const regex = new RegExp(`(${term})`, 'gi');
            return text.replace(regex, '<span class="highlight">$1</span>');
        }

        function filterTable() {
            const searchTerm = document.getElementById('searchInput').value.toLowerCase();

            filteredData = sampleData.filter(row => {
                return Object.values(row).some(val =>
                    String(val).toLowerCase().includes(searchTerm)
                );
            });

            if (currentSort.column >= 0) {
                sortData(filteredData, currentSort.column, currentSort.ascending);
            }

            renderTable(filteredData);
            updateSortIndicators();
        }

        function sortTable(columnIndex) {
            const isAscending = currentSort.column === columnIndex ? !currentSort.ascending : true;
            currentSort = { column: columnIndex, ascending: isAscending };

            sortData(filteredData, columnIndex, isAscending);
            renderTable(filteredData);
            updateSortIndicators();
        }

        function sortData(data, columnIndex, ascending) {
            const keys = ['name', 'status', 'type', 'created', 'details'];
            const key = keys[columnIndex];

            data.sort((a, b) => {
                const aVal = String(a[key]).toLowerCase();
                const bVal = String(b[key]).toLowerCase();

                if (aVal < bVal) return ascending ? -1 : 1;
                if (aVal > bVal) return ascending ? 1 : -1;
                return 0;
            });
        }

        function updateSortIndicators() {
            document.querySelectorAll('th .sort-indicator').forEach((el, idx) => {
                if (idx === currentSort.column) {
                    el.textContent = currentSort.ascending ? '▲' : '▼';
                    el.style.color = '#0066cc';
                } else {
                    el.textContent = '';
                    el.style.color = '#999';
                }
            });
        }

        document.getElementById('searchInput').addEventListener('input', filterTable);
        document.getElementById('totalCount').textContent = sampleData.length;

        renderTable(sampleData);
    </script>
